// flashcard drill — JAH Color Theory Database (jahdb demo program)
var ITEMS=[["Primary colors (RYB)","Red, yellow, blue: the traditional painter primaries."], ["Primary colors (CMY)","Cyan, magenta, yellow: the printing primaries."], ["Secondary colors","Orange, green, violet: primaries mixed pairwise."], ["Tertiary colors","Red-orange, yellow-green, etc.: primary plus secondary."], ["Hue","The color family: red, blue, green."], ["Saturation","Color intensity: vivid vs gray."], ["Value","Lightness or darkness."], ["Tint","Hue plus white."], ["Shade","Hue plus black."], ["Tone","Hue plus gray."], ["Complementary","Opposites on the wheel: red-green, blue-orange."], ["Analogous","Neighbors on the wheel."], ["Triadic","Three evenly spaced hues."], ["Split-complementary","One hue plus the two beside its complement."], ["Tetradic","Two complementary pairs."], ["Monochromatic","One hue in many values."], ["Warm colors","Reds, oranges, yellows: advance and energize."], ["Cool colors","Blues, greens, violets: recede and calm."], ["Red psychology","Energy, urgency, appetite."], ["Blue psychology","Trust, calm, professionalism."], ["Green psychology","Nature, health, calm."], ["Yellow psychology","Optimism, attention, caution."], ["Purple psychology","Luxury, creativity."], ["Orange psychology","Friendly energy."], ["Black psychology","Elegance, power."], ["White psychology","Cleanliness, simplicity."], ["Simultaneous contrast","Colors shift each other: gray looks different on different grounds."], ["Afterimage","Staring creates complementary ghosts."], ["Bezold effect","Same color looks different with different neighbors."], ["Chromatic adaptation","Eyes adjust to lighting color."]];
function ask(n){var out=[],seen={};n=Math.min(n,ITEMS.length);for(var k=0;k<n;k++){var it=ITEMS[(Math.random()*ITEMS.length)|0];out.push("Q"+(k+1)+": "+it[0]+"\nA"+(k+1)+": "+it[1]);}return out.join("\n\n");}
function lookup(q){q=String(q).toLowerCase();var h=[];for(var i=0;i<ITEMS.length;i++){if((ITEMS[i][0]+" "+ITEMS[i][1]).toLowerCase().indexOf(q)>=0)h.push(ITEMS[i][0]+" — "+ITEMS[i][1]);}return h.length?h.join("\n"):"no match for "+q;}
console.log("== drill ==");console.log(ask(5));

